const cache = new Map();

function cacheMiddleware(req, res, next) {
  const key = req.url;
  if (cache.has(key)) {
    return res.json(cache.get(key));
  }
  // Intercept res.json to cache before sending
  const originalJson = res.json.bind(res);
  res.json = (data) => {
    cache.set(key, data);
    originalJson(data);
  };
  next();
}

